class Solution {
public:
    vector<int> findKDistantIndices(vector<int>& nums, int key, int k) {
        vector<int> ans;
        int n = nums.size();
        int nxt = 0;
        for (int j = 0; j < n; j++) {
            if (nums[j] == key) {
                int start = max(nxt, j - k);
                int end = min(n - 1, j + k);
                for (int i = start; i <= end; i++) {
                    ans.push_back(i);
                }
                nxt = end + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public List<Integer> findKDistantIndices(int[] nums, int key, int k) {
        List<Integer> ans = new ArrayList<>();
        int n = nums.length;
        int nxt = 0;
        for (int j = 0; j < n; j++) {
            if (nums[j] == key) {
                int start = Math.max(nxt, j - k);
                int end = Math.min(n - 1, j + k);
                for (int i = start; i <= end; i++) {
                    ans.add(i);
                }
                nxt = end + 1;
            }
        }
        return ans;
    }
}

