var findKDistantIndices = function(nums, key, k) {
    const ans = [];
    const n = nums.length;
    let nxt = 0;
    for (let j = 0; j < n; j++) {
        if (nums[j] === key) {
            const start = Math.max(nxt, j - k);
            const end = Math.min(n - 1, j + k);
            for (let i = start; i <= end; i++) {
                ans.push(i);
            }
            nxt = end + 1;
        }
    }
    return ans;
};
